#!/usr/bin/env python3
"""Render the beneficiary v0.2 human-audit page."""

from __future__ import annotations

import argparse
import json
from pathlib import Path


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser()
    parser.add_argument(
        "--input-json",
        type=Path,
        default=Path("data/processed/beneficiary_v0_2/beneficiary_v0_2.json"),
    )
    parser.add_argument(
        "--output-html",
        type=Path,
        default=Path("data/processed/beneficiary_v0_2/beneficiary_v0_2_audit.html"),
    )
    return parser.parse_args()


TEMPLATE = r"""<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Beneficiary audit · v0.2</title><style>
:root{--bg:#071321;--panel:#101f32;--panel2:#14263c;--line:#304862;--text:#f3f7ff;--muted:#aebcd0;--cyan:#45e0d0;--pink:#ff51c7;--violet:#c58cff;--gold:#ffd052;--red:#ff6d5b;--blue:#438dff;--green:#65dda0;--orange:#ff9c43}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:Inter,Pretendard,system-ui,sans-serif}main{max-width:1740px;margin:auto;padding:20px}h1{margin:0 0 5px;font-size:1.9rem}h2,h3{margin:0 0 8px}p{color:var(--muted);line-height:1.45}.notice{border-left:4px solid var(--gold);background:#192a42;padding:10px 14px;border-radius:7px;margin:10px 0}.controls{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin:9px 0}.grow{flex:1}select,button{font:inherit;color:var(--text);background:#192b43;border:1px solid #4a6483;border-radius:8px;padding:8px 11px}button.active{border-color:var(--gold);color:var(--gold);background:#2a2940}.layout{display:grid;grid-template-columns:minmax(790px,1fr) 580px;gap:15px}.panel{background:var(--panel);border:1px solid var(--line);border-radius:13px;padding:14px}.pitch{display:block;width:100%;background:#17743a;border-radius:9px}.scrub{width:100%}.time{font-variant-numeric:tabular-nums}.legend{display:flex;gap:13px;flex-wrap:wrap;color:#cbd6e6;font-size:.82rem;margin-top:8px}.sw{display:inline-block;width:19px;border-top:4px solid;margin-right:5px}.status{display:inline-block;border-radius:99px;padding:4px 9px;font-size:.8rem;font-weight:800}.selected-status{background:#224b3f;color:#7ff0bc}.none-status{background:#4a3021;color:#ffca8e}.candidate-table{width:100%;border-collapse:collapse;font-size:.8rem;margin-top:8px}.candidate-table th{text-align:right;color:#aebcd0;padding:6px 5px;border-bottom:1px solid #415872}.candidate-table th:first-child,.candidate-table td:first-child{text-align:left}.candidate-table td{text-align:right;padding:7px 5px;border-bottom:1px solid #263d56}.candidate-table tbody tr{cursor:pointer}.candidate-table tbody tr:hover{background:#19304a}.candidate-table tbody tr.active{background:#203b55;outline:1px solid var(--violet)}.candidate-table .bad{color:#8391a4}.box{background:var(--panel2);border:1px solid #2d445f;border-radius:9px;padding:10px;margin-top:9px;line-height:1.45}.metrics{display:grid;grid-template-columns:repeat(5,1fr);gap:6px;margin-top:9px}.metric{background:#152a40;border-radius:8px;padding:8px;min-height:66px}.metric span{font-size:.74rem;color:var(--muted)}.metric strong{display:block;font-size:1.05rem;margin-top:4px}.positive{color:var(--green)}.weak{color:var(--orange)}.components{display:grid;grid-template-columns:1fr 1fr;gap:7px}.component{background:#102033;padding:8px;border-radius:7px}.component b{float:right}.release{display:flex;gap:5px;flex-wrap:wrap}.tick{font-size:.74rem;padding:4px 7px;background:#203750;border-radius:99px}.tick.peak{background:#543d69;color:#f1d9ff}.small{font-size:.82rem;color:var(--muted)}.review{border-left:3px solid #71849d;padding-left:9px}.warn{color:#ffd082}@media(max-width:1220px){.layout{grid-template-columns:1fr}.metrics{grid-template-columns:repeat(3,1fr)}}
</style></head><body><main><h1>Follow-induced beneficiary audit · v0.2</h1><p class="notice"><b>질문:</b> relevant defender가 runner를 goal-side로 따라가면 누구의 패스·carry 옵션이 열리고, 그 후보를 막으러 가면 runner가 다시 얼마나 위험해지는가? V0의 시간 변화는 선정에 사용하지 않는다.</p><div class="controls"><label>장면 <select class="scene"></select></label><button class="prev">← 이전</button><button class="next">다음 →</button><button class="play">▶ 재생</button><span class="time"></span><span class="grow"></span><span class="scene-status"></span></div><div class="layout"><section class="panel"><div class="controls responses"><b>수비 보기</b><button data-response="actual">실제 수비</button><button data-response="runner" class="active">Runner 따라가기</button><button data-response="beneficiary">검토 후보 방어</button></div><svg class="pitch" viewBox="0 0 105 68"><rect width="105" height="68" fill="#17743a" stroke="white" stroke-width=".3"/><line x1="52.5" x2="52.5" y1="0" y2="68" stroke="white" stroke-width=".25"/><circle cx="52.5" cy="34" r="9.15" fill="none" stroke="white" stroke-width=".25"/><rect x="0" y="13.84" width="16.5" height="40.32" fill="none" stroke="white" stroke-width=".25"/><rect x="88.5" y="13.84" width="16.5" height="40.32" fill="none" stroke="white" stroke-width=".25"/><g class="static"></g><g class="moving"></g></svg><input class="scrub" type="range" min="0" value="0"><div class="legend"><span><i class="sw" style="border-color:var(--pink)"></i>runner 실제</span><span><i class="sw" style="border-color:var(--violet)"></i>검토 중인 후보</span><span><i class="sw" style="border-color:var(--violet);border-top-style:dashed"></i>패스/carry 옵션</span><span><i class="sw" style="border-color:white;border-top-style:dashed"></i>실제 수비</span><span><i class="sw" style="border-color:var(--cyan)"></i>가상 수비</span></div><p class="small">먼저 Runner 따라가기를 재생한 뒤 검토 후보 방어와 비교한다. 보라색 선은 follow branch에서 열린 구체적인 패스/carry 옵션이다.</p></section><aside class="panel"><h2 class="title"></h2><p class="subtitle"></p><div class="metrics"><div class="metric"><span>Follow 시 후보</span><strong class="vf"></strong></div><div class="metric"><span>후보 방어 시</span><strong class="vc"></strong></div><div class="metric"><span>Follow benefit</span><strong class="benefit"></strong></div><div class="metric"><span>Follow 시 Runner</span><strong class="rf"></strong></div><div class="metric"><span>Runner cost</span><strong class="rcost"></strong></div></div><div class="box explanation"></div><div class="box"><h3>후보 전체 비교</h3><table class="candidate-table"><thead><tr><th>선수</th><th>Follow</th><th>후보 방어</th><th>Follow 이득</th><th>Runner 비용</th></tr></thead><tbody></tbody></table><p class="small">두 cross-cost가 모두 양수인 후보만 통과한다. 포지션은 설명용이며 필터로 사용하지 않는다.</p></div><div class="box"><h3>Follow → 후보 방어 시 옵션 구성 변화</h3><div class="components"><div class="component">패스/실행 확률 <b class="prob"></b></div><div class="component">Goal danger <b class="goal"></b></div><div class="component">패스 경로 생존 <b class="lane"></b></div><div class="component">수신 경쟁 승리 <b class="race"></b></div></div></div><div class="box"><h3>평가한 패스 릴리스 시점</h3><div class="release"></div><p class="small release-note"></p></div><div class="box review"></div><p class="small warn">V0 변화는 참고값일 뿐 beneficiary를 고르지 않는다. 현재 effect-size threshold는 수치오차 기준만 적용했다.</p></aside></div></main><script id="data" type="application/json">__DATA__</script><script>
const DATA=JSON.parse(document.getElementById('data').textContent);let si=0,ci=0,mode='runner',fi=0,playing=false,timer=null;const $=s=>document.querySelector(s),S=()=>DATA[si],C=()=>S().candidates[ci],px=x=>52.5+S().attacking_direction*x,py=y=>34-y,fmt=v=>Number(v).toFixed(3),gain=v=>(v>=0?'+':'')+Number(v).toFixed(3);
function player(frame,id){let p=frame.players.find(x=>x[0]===id);return p?[p[2],p[3]]:null}function interp(ts,xy,t){if(t<=ts[0])return xy[0];if(t>=ts.at(-1))return xy.at(-1);let i=ts.findIndex(x=>x>=t),a=(t-ts[i-1])/(ts[i]-ts[i-1]);return[xy[i-1][0]+a*(xy[i][0]-xy[i-1][0]),xy[i-1][1]+a*(xy[i][1]-xy[i-1][1])]}function actualAt(t){let p=S().actual_response.path_txy;if(t<=0)return[p[0][1],p[0][2]];if(t>=p.at(-1)[0])return[p.at(-1)[1],p.at(-1)[2]];let i=p.findIndex(x=>x[0]>=t),a=(t-p[i-1][0])/(p[i][0]-p[i-1][0]);return[p[i-1][1]+a*(p[i][1]-p[i-1][1]),p[i-1][2]+a*(p[i][2]-p[i-1][2])]}
function pathFor(response){return response.times_s.map((t,i)=>[t,...response.path_xy[i]])}function observedPath(id){return S().background_frames.filter(f=>f.time_s>=0).map(f=>[f.time_s,...player(f,id)])}function poly(path,color,dash='',width=.5,opacity=1){return`<polyline points="${path.map(p=>px(p[1])+','+py(p[2])).join(' ')}" fill="none" stroke="${color}" stroke-width="${width}" stroke-dasharray="${dash}" opacity="${opacity}"/>`}
function response(){if(mode==='runner')return S().runner_follow_response;if(mode==='beneficiary')return C().best_cover_response;return null}function frameAtPeak(){let t=C().peak_time_s,frames=S().background_frames;return frames.reduce((a,b)=>Math.abs(b.time_s-t)<Math.abs(a.time_s-t)?b:a)}
function drawStatic(){let s=S(),c=C(),peak=frameAtPeak(),ball=peak.ball,html=poly(observedPath(s.runner_id),'#ff51c7','',.55)+poly(observedPath(c.player_id),'#c58cff','1 .55',.42,.85)+poly(s.actual_response.path_txy,'white','1 .55',.38,.9);let r=response();if(r)html+=poly(pathFor(r),'#45e0d0','',.58);if(ball)html+=`<line x1="${px(ball[0])}" y1="${py(ball[1])}" x2="${px(c.event_x)}" y2="${py(c.event_y)}" stroke="#c58cff" stroke-width=".34" stroke-dasharray="1 .5" opacity=".9"/><circle cx="${px(c.event_x)}" cy="${py(c.event_y)}" r=".75" fill="none" stroke="#c58cff" stroke-width=".3"/><text x="${px(c.event_x)+1}" y="${py(c.event_y)-1}" fill="#f0dcff" font-size="1.5">${c.option_type==='carry_or_shot'?'carry/shot':'receive'} @${c.peak_time_s.toFixed(2)}s</text>`;$('.static').innerHTML=html}
function drawFrame(){let s=S(),c=C(),f=s.background_frames[fi],t=f.time_s,r=response(),actual=t<0?player(f,s.defender_id):actualAt(t),virt=r?(t<0?actual:interp(r.times_s,r.path_xy,t)):actual;let hidden=[s.runner_id,s.defender_id,c.player_id],html=f.players.filter(p=>!hidden.includes(p[0])).map(p=>`<circle cx="${px(p[2])}" cy="${py(p[3])}" r=".67" fill="${p[1]===s.attacking_team_id?'#ff6d5b':'#438dff'}" stroke="white" stroke-width=".12"><title>${s.names[p[0]]||p[0]}</title></circle>`).join('');if(f.ball)html+=`<circle cx="${px(f.ball[0])}" cy="${py(f.ball[1])}" r=".4" fill="#111" stroke="white" stroke-width=".14"/>`;let rp=player(f,s.runner_id),cp=player(f,c.player_id);html+=`<circle cx="${px(rp[0])}" cy="${py(rp[1])}" r="1.02" fill="#ff51c7" stroke="white" stroke-width=".2"><title>${s.runner_name}</title></circle>`;if(cp)html+=`<circle cx="${px(cp[0])}" cy="${py(cp[1])}" r=".95" fill="#ff6d5b" stroke="#c58cff" stroke-width=".45"><title>${c.player_name}</title></circle>`;html+=`<circle cx="${px(actual[0])}" cy="${py(actual[1])}" r="1.15" fill="none" stroke="white" stroke-width=".3"/>`;if(r)html+=`<circle cx="${px(virt[0])}" cy="${py(virt[1])}" r=".87" fill="#438dff" stroke="#45e0d0" stroke-width=".42"/>`;$('.moving').innerHTML=html;$('.scrub').value=fi;$('.time').textContent=`t=${t>=0?'+':''}${t.toFixed(2)}초`}
const reasonMap={no_legal_option:'합법적 옵션 없음',not_attacking_option:'공격 진영 옵션 아님',no_follow_benefit:'따라가도 후보가 더 열리지 않음',no_runner_cost:'후보를 막아도 runner가 더 위험해지지 않음'};function renderCandidates(){let s=S();$('.candidate-table tbody').innerHTML=s.candidates.map((c,i)=>`<tr data-i="${i}" class="${i===ci?'active':''} ${c.eligible?'':'bad'}"><td><b>${c.player_name}</b><br><span class="small">${c.position||'?'} · ${c.option_type==='carry_or_shot'?'carry/shot':'pass'}</span></td><td>${fmt(c.follow_value)}</td><td>${fmt(c.best_cover_value)}</td><td>${gain(c.follow_benefit)}</td><td>${gain(c.runner_cost)}</td></tr>`).join('');document.querySelectorAll('.candidate-table tbody tr').forEach(x=>x.onclick=()=>{ci=Number(x.dataset.i);renderAll()})}
function transition(a,b){return(100*a).toFixed(1)+'% → '+(100*b).toFixed(1)+'%'}function details(){let s=S(),c=C(),selected=s.selected_beneficiary_id===c.player_id,reasons=c.rejection_reasons.map(x=>reasonMap[x]||x),f=c.follow_components,b=c.best_cover_components;$('.vf').textContent=fmt(c.follow_value);$('.vc').textContent=fmt(c.best_cover_value);$('.benefit').textContent=gain(c.follow_benefit);$('.benefit').className='benefit '+(c.follow_benefit>0?'positive':'weak');$('.rf').textContent=fmt(c.runner_follow_value);$('.rcost').textContent=gain(c.runner_cost);$('.rcost').className='rcost '+(c.runner_cost>0?'positive':'weak');$('.explanation').innerHTML=`<h3>${c.player_name} <span class="status ${c.eligible?'selected-status':'none-status'}">${selected?'provisional selected':c.eligible?'eligible candidate':'제외'}</span></h3>${c.option_type==='carry_or_shot'?'볼 소유자의 carry/shot 지속 옵션':'볼 소유자에서 이 선수의 도달 가능한 수신 영역으로 가는 패스 옵션'}<br>대표 event <b>(${c.event_x.toFixed(1)}, ${c.event_y.toFixed(1)}) @ ${c.peak_time_s.toFixed(2)}초</b><br>두 수비 branch 평균 거리 <b>${c.mean_response_separation_m.toFixed(1)}m</b> · 주 억제 메커니즘 <b>${c.suppression_mechanism}</b><br><span class="small">참고 V0 ${fmt(c.onset_value)} · 시간 변화 ${gain(c.temporal_gain_from_v0)} (선정에 미사용)</span>${reasons.length?`<br><span class="warn">제외 이유: ${reasons.join(', ')}</span>`:'<br><span class="positive">Follow benefit과 Runner cost가 모두 양수다.</span>'}`;$('.prob').textContent=transition(f.receive_probability,b.receive_probability);$('.goal').textContent=transition(f.goal_value,b.goal_value);$('.lane').textContent=transition(f.path_survival_probability,b.path_survival_probability);$('.race').textContent=transition(f.receiver_first_probability,b.receiver_first_probability);$('.release').innerHTML=s.release_times_s.map(t=>`<span class="tick ${Math.abs(t-c.peak_time_s)<.01?'peak':''}">${t.toFixed(2)}s</span>`).join('');$('.release-note').textContent=`${s.ball_owner_name}가 계속 소유한 실제 릴리스 window · ${s.release_window_reason}`;$('.review').innerHTML=`기존 검수: onset <b>${s.review.onset}</b> · possession <b>${s.review.possession}</b> · interaction <b>${s.review.interaction}</b>${s.review.note?`<br>${s.review.note}`:''}`}
function sceneInfo(){let s=S(),a=s.runner_follow_anchor;$('.title').textContent=`${s.runner_name} · defender ${s.defender_name}`;$('.subtitle').innerHTML=`볼 소유자 <b>${s.ball_owner_name}</b> · ${s.response_count}개 feasible response · ${s.match_label}<br>Follow anchor 평균 goal-side tracking error <b>${a.tracking_error_m.toFixed(1)}m</b>`;$('.scene-status').innerHTML=s.selected_beneficiary_name?`<span class="status selected-status">잠정 beneficiary · ${s.selected_beneficiary_name}</span>`:`<span class="status none-status">식별된 beneficiary 없음</span>`}
function renderAll(){drawStatic();drawFrame();renderCandidates();details();sceneInfo()}function setScene(i){si=(Number(i)+DATA.length)%DATA.length;ci=Math.max(0,DATA[si].candidates.findIndex(c=>c.player_id===DATA[si].selected_beneficiary_id));fi=0;$('.scene').value=si;$('.scrub').max=DATA[si].background_frames.length-1;renderAll()}
function init(){let sel=$('.scene');sel.innerHTML=DATA.map((s,i)=>`<option value="${i}">${i+1}. ${s.runner_name} · frame ${s.onset_frame_id}</option>`).join('');sel.onchange=e=>setScene(e.target.value);$('.prev').onclick=()=>setScene(si-1);$('.next').onclick=()=>setScene(si+1);$('.scrub').oninput=e=>{fi=Number(e.target.value);drawFrame()};document.querySelectorAll('.responses button').forEach(b=>b.onclick=()=>{mode=b.dataset.response;document.querySelectorAll('.responses button').forEach(x=>x.classList.toggle('active',x===b));drawStatic();drawFrame()});$('.play').onclick=e=>{playing=!playing;e.target.textContent=playing?'❚❚ 일시정지':'▶ 재생';if(playing)timer=setInterval(()=>{fi=fi>=S().background_frames.length-1?0:fi+1;drawFrame()},70);else clearInterval(timer)};setScene(0)}init();
</script></body></html>"""


def main() -> None:
    args = parse_args()
    payload = json.loads(args.input_json.read_text(encoding="utf-8"))
    args.output_html.parent.mkdir(parents=True, exist_ok=True)
    args.output_html.write_text(
        TEMPLATE.replace("__DATA__", json.dumps(payload, ensure_ascii=False)),
        encoding="utf-8",
    )
    print(f"audit: {args.output_html.resolve()}")


if __name__ == "__main__":
    main()
